      "card_id": "kinase-react",
      "instruction": "In 384‑well plates combine: recombinant mTOR (final 5 nM), peptide substrate 4E‑BP1 (final 1 µM), ATP (final 100 µM, saturating relative to Km), and each compound dilution. Incubate 30 min at 30 °C.",
      "parameters": {
        "enzyme_concentration": "5 nM (typical for ADP‑Glo mTOR assays, see published mTOR ADP‑Glo protocols)",
